(()=>{
const savedCard=document.querySelector('#saved-device-card');if(!savedCard)return;
let activeModel=null;
function phase(value){document.body.dataset.compatPhase=value;document.querySelector('.site-header').inert=value==='scanning';document.querySelector('.site-footer').inert=value==='scanning';document.querySelector('.compat-setup').inert=value==='scanning';}
phase('setup');
const start=document.querySelector('#compat-start');const results=document.querySelector('#compat-results');const visual=document.querySelector('#compat-visual');const progress=document.querySelector('#compat-progress');const iosInput=document.querySelector('#compat-ios');const storageInput=document.querySelector('#compat-storage');const requiredBlock=document.querySelector('.optional-checks');const requiredInputs=[iosInput,storageInput].filter(Boolean);let data=null;let busy=false;let refreshPending=false;
function setupRequiredDetails(){
 if(!requiredBlock)return;
 requiredBlock.open=true;requiredBlock.classList.add('required-checks');requiredBlock.setAttribute('open','');
 const summary=requiredBlock.querySelector('summary');
 if(summary){const badge=summary.querySelector('span');summary.childNodes[0].nodeValue='iOS and storage details ';if(badge)badge.textContent='Required';summary.setAttribute('aria-label','iOS and storage details. Required.');summary.addEventListener('click',event=>event.preventDefault());}
 requiredBlock.addEventListener('toggle',()=>{if(!requiredBlock.open)requiredBlock.open=true});
 requiredInputs.forEach(input=>{input.required=true;input.setAttribute('aria-required','true')});
 const note=requiredBlock.querySelector(':scope>p');if(note)note.textContent='Required. Enter both values from Settings before starting. The browser cannot read them.';
 if(!document.querySelector('#compat-required-style')){const style=document.createElement('style');style.id='compat-required-style';style.textContent='.optional-checks.required-checks{margin:19px 0 22px;padding:15px 16px 16px;border:1px solid rgba(232,182,94,.24);border-radius:8px;background:linear-gradient(180deg,rgba(232,182,94,.055),rgba(255,255,255,.015));transition:border-color .2s ease,background .2s ease}.optional-checks.required-checks summary{padding:0 0 13px!important;color:var(--fg-d8d8d5,#d8d8d5)!important;font-weight:600;cursor:default;pointer-events:none;list-style:none}.optional-checks.required-checks summary::-webkit-details-marker{display:none}.optional-checks.required-checks summary span{color:var(--fd-accent,#e8b65e)!important;border-color:rgba(232,182,94,.38)!important;background:rgba(232,182,94,.07)}.optional-checks.required-checks .optional-fields{margin-top:0}.optional-checks.required-checks .optional-fields label{color:var(--fg-b0b0b0,#b0b0b0)}.optional-checks.required-checks .optional-fields input{border-color:rgba(232,182,94,.28)}.optional-checks.required-checks .optional-fields input:focus{outline:none;border-color:#e8b65e;box-shadow:0 0 0 2px rgba(232,182,94,.12)}.optional-checks.required-checks>p{margin-bottom:0;color:var(--fg-888888,#888)}.optional-checks.required-checks.is-complete{border-color:rgba(137,178,116,.38);background:linear-gradient(180deg,rgba(137,178,116,.045),rgba(255,255,255,.015))}@media(max-width:520px){.optional-checks.required-checks .optional-fields{grid-template-columns:1fr;gap:12px}}';document.head.append(style);}
}
function requiredDetailsValid(){return requiredInputs.length===2&&requiredInputs.every(input=>input.value.trim()!==''&&input.checkValidity())}
function updateStartState(){const complete=requiredDetailsValid();if(requiredBlock)requiredBlock.classList.toggle('is-complete',complete);start.disabled=!(data&&activeModel&&!busy&&complete)}
setupRequiredDetails();updateStartState();
const el=(tag,className,text)=>{const item=document.createElement(tag);if(className)item.className=className;if(text)item.textContent=text;return item};
const svg=(name)=>{const node=document.createElementNS('http://www.w3.org/2000/svg','svg');node.classList.add('icon');node.setAttribute('aria-hidden','true');node.setAttribute('focusable','false');const use=document.createElementNS(node.namespaceURI,'use');use.setAttribute('href','assets/icons.svg#'+name);node.append(use);return node};
const badge=(state)=>{const node=el('span','hardware-badge '+state.level);node.append(svg(state.level==='critical'?'warning':state.level==='headroom'?'check':'info'),document.createTextNode(state.label));return node};
function sourceLink(label,url){const link=el('a','',label);link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.append(svg('arrow-up-right'));return link}
function card(label,value,note,iconName,state){const item=el('article','hardware-card '+(state?.level||'information'));const top=el('div','hardware-card-top');const name=el('span','hardware-label',label);top.append(svg(iconName),name);if(state)top.append(badge(state));item.append(top,el('h3','',value),el('p','',note));return item}
function render(model){phase('results');performanceAssistant.reset(model);const baseline=data.baseline;const memory=compatibilityRules.memory(model.ram,baseline.ramGB);const ios=compatibilityRules.entry(iosInput.value,baseline.ios,'iOS');const storage=compatibilityRules.entry(storageInput.value,baseline.freeStorageGB,'GB');const invalidIOS=iosInput.validity.valid;const invalidStorage=storageInput.validity.valid;if(!invalidIOS){ios.level='unknown';ios.label='Invalid entry';ios.value='Check your entry';ios.note='Use an iOS version between 1 and 99.'}if(!invalidStorage){storage.level='unknown';storage.label='Invalid entry';storage.value='Check your entry';storage.note='Use a valid non-negative storage value.'}
document.querySelector('#compat-result-title').textContent=model.name;const verdict=document.querySelector('#compat-verdict');verdict.className='compat-verdict '+memory.level;const verdictIcon=el('div','verdict-icon');verdictIcon.append(svg(memory.level==='critical'?'warning':memory.level==='headroom'?'check':'info'));const summary=el('div');let heading=memory.title;let note=memory.note;if([ios,storage].some(check=>check.level==='critical')){heading='One or more checker guidelines are not met';note='Review the highlighted checks below. More RAM does not override an unsupported iOS version or insufficient storage.';verdict.className='compat-verdict critical'}else if(memory.level==='headroom'&&ios.level==='headroom'&&storage.level==='headroom'){heading='Meets the reference checks';note='Installed RAM and the iOS and storage values you provided meet the checker baseline. This is not a game test or certification.'}summary.append(el('h3','',heading),el('p','',note));verdict.replaceChildren(verdictIcon,summary);
document.querySelector('#memory-support').hidden=memory.level!=='critical';
const grid=document.querySelector('#hardware-grid');grid.replaceChildren(card('System on chip',model.chip||'Unverified','Apple silicon model. CPU, GPU, and Neural Engine are integrated into this chip.','cpu'),card('CPU',model.cpu?model.cpu+' cores':'Unverified','Central processing unit. Core counts are hardware specifications, not performance scores.','cpu'),card('GPU',model.gpu?model.gpu+' cores':'Unverified','Graphics processing unit. Rendering performance also depends on the port and its settings.','layers'),card('Installed RAM',model.ram!==null?model.ram+' GB':'Unverified',memory.note,'memory',memory),card('Neural Engine',model.neural||'Unverified','Machine-learning hardware. Its presence is not a GTA V compatibility requirement.','cpu'),card('Assessment type','Saved model profile','Hardware lookup from your welcome answer. No live RAM, temperature, or performance measurement.','info'));
const runtime=document.querySelector('#runtime-grid');runtime.replaceChildren(card('Installed iOS',ios.value,ios.note,'gamepad',ios),card('Free storage',storage.value,storage.note,'storage',storage));const links=document.querySelector('#compat-source-links');links.replaceChildren(sourceLink('Apple: hardware specifications',model.appleSource));if(model.ramSource){const source=data.sources[model.ramSource];links.append(sourceLink(source.label,source.url))}else links.append(el('p','source-unknown','RAM source: not yet verified for this model.'));const reference=data.sources[baseline.source];links.append(sourceLink(reference.label,reference.url),el('p','source-review','Sources reviewed '+data.reviewed+'. '+baseline.note));results.hidden=false;results.querySelectorAll('.hardware-card').forEach((item,index)=>item.style.setProperty('--card-delay',index*45+'ms'));document.querySelector('#chip-preview').textContent=model.chip||'UNVERIFIED';document.querySelector('#compat-visual-title').textContent='Profile ready.';progress.textContent='Review the hardware and highlighted checks below.';document.querySelector('#compat-result-title').focus();results.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
const stages=[...document.querySelectorAll('[data-review-step]')];
function setStage(index,complete=false){stages.forEach((item,i)=>{item.classList.toggle('active',!complete&&i===index);item.classList.toggle('done',complete||i<index);});document.querySelector('#review-state').textContent=complete?'REVIEW COMPLETE':`PROFILE REVIEW / ${index+1} OF 3`;}
function invalidate(){phase('setup');results.hidden=true;visual.classList.remove('profile-ready');document.querySelector('#compat-visual-title').textContent='Ready to review.';progress.textContent='Press Start to review your saved device.';start.firstChild.textContent='Start ';stages.forEach(item=>item.classList.remove('active','done'));document.querySelector('#review-state').textContent='SAVED PROFILE';updateStartState();}
start.addEventListener('click',async()=>{
 if(!data||!activeModel||busy||!requiredDetailsValid())return;
 phase('scanning');window.scrollTo({top:0,behavior:'instant'});visual.setAttribute('tabindex','-1');visual.focus();busy=true;updateStartState();visual.classList.add('reviewing');visual.classList.remove('profile-ready');visual.setAttribute('aria-busy','true');results.hidden=true;start.firstChild.textContent='Reviewing ';
 const labels=['Loading the hardware profile from your welcome answer…','Comparing installed memory with planning guidelines…','Preparing your hardware and installation checks…'];
 const delay=matchMedia('(prefers-reduced-motion: reduce)').matches?0:480;
 try{for(let i=0;i<labels.length;i++){setStage(i);progress.textContent=labels[i];if(delay)await new Promise(resolve=>setTimeout(resolve,delay));}render(activeModel);setStage(2,true);visual.classList.add('profile-ready');}
 finally{busy=false;start.firstChild.textContent='Check again ';visual.classList.remove('reviewing');visual.removeAttribute('aria-busy');updateStartState();if(refreshPending){refreshPending=false;invalidate();init();}}
});
requiredInputs.forEach(input=>input.addEventListener('input',()=>{updateStartState();if(!results.hidden){invalidate();progress.textContent='Details changed. Press Start to update your results.';}}));
document.querySelector('#compat-details').addEventListener('click',()=>{invalidate();requiredBlock.open=true;iosInput.focus();requiredBlock.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});});
function readWelcome(){try{return JSON.parse(localStorage.getItem('gtav-community-onboarding')||sessionStorage.getItem('gtav-community-onboarding')||'null')}catch{try{return JSON.parse(sessionStorage.getItem('gtav-community-onboarding')||'null')}catch{return null}}}
function showUnavailable(state){
 activeModel=null;start.hidden=true;requiredBlock.hidden=true;document.querySelector('.review-steps').hidden=true;
 document.querySelector('#profile-notice').hidden=false;savedCard.dataset.state=state.status;
 const android=state.status==='android';document.querySelector('#saved-device-name').textContent=android?'Android device':state.name||'No saved iPhone';
 document.querySelector('#saved-device-label').textContent=android?'DEVICE NOT SUPPORTED':'WELCOME PROFILE REQUIRED';
 document.querySelector('#saved-device-note').textContent=android?'Your welcome answer is Android. This project supports iOS devices.':'An exact iPhone model is needed for a reliable hardware lookup.';
 document.querySelector('#profile-notice-text').textContent=android?'You can still browse the project and community. If your welcome answer was incorrect, update it through the welcome form.':state.status==='unknown'?'The saved model is not in this catalog. Please update your welcome answer; no replacement model has been assumed.':'Complete the welcome form to record your device before reviewing its hardware.';
 document.querySelector('#profile-notice a').firstChild.textContent=android?'Update welcome answers ':'Complete welcome setup ';
 document.querySelector('#chip-preview').textContent=android?'ANDROID':'NO PROFILE';document.querySelector('#compat-visual-title').textContent=android?'iOS only.':'Profile needed.';progress.textContent=android?'No iPhone hardware profile has been assigned.':'Your device will appear here after welcome setup.';document.querySelector('#review-state').textContent=android?'UNSUPPORTED PLATFORM':'SETUP REQUIRED';updateStartState();
}
async function init(){
 try{const response=await fetch('compatibility-data.json',{cache:'no-cache'});if(!response.ok)throw Error('Profiles unavailable');data=await response.json();const saved=savedDeviceProfile.resolve(readWelcome(),data.models);
 if(saved.status!=='ready'){showUnavailable(saved);return;}
 start.hidden=false;requiredBlock.hidden=false;requiredBlock.open=true;document.querySelector('.review-steps').hidden=false;document.querySelector('#profile-notice').hidden=true;activeModel=saved.model;savedCard.dataset.state='ready';document.querySelector('#saved-device-name').textContent=activeModel.name;document.querySelector('#saved-device-label').textContent='SAVED FROM WELCOME';document.querySelector('#saved-device-note').textContent='This is the model you provided. Hardware details come from the source-based catalog.';document.querySelector('#chip-preview').textContent=activeModel.chip||'UNVERIFIED';updateStartState();
 }catch{savedCard.dataset.state='error';document.querySelector('#saved-device-name').textContent='Profile unavailable';const error=document.querySelector('#compat-error');error.textContent='Device profiles could not be loaded. Refresh the page to try again. Your saved welcome answer has not changed.';error.hidden=false;progress.textContent='Waiting for the hardware catalog.';updateStartState();}
}
window.addEventListener('storage',event=>{if(event.key==='gtav-community-onboarding'){if(busy)refreshPending=true;else{invalidate();init();}}});
init();
})();
